    it("renders a blank poll", () => {
        const dialog = mount(
            <PollCreateDialog room={createRoom()} onFinished={jest.fn()} />,
        );
        expect(dialog).toMatchSnapshot();
    });

    it("renders a question and some options", () => {
        const dialog = mount(
            <PollCreateDialog room={createRoom()} onFinished={jest.fn()} />,
